import axios from "axios";
import { updateUIAfterDelete } from "./update"; // Import update function

export const handleDeleteImage = (category, imageUrl, setConfirmDelete) => {
  setConfirmDelete({ category, imageUrl, type: "single" });
};

export const handleDeleteAll = (category, setConfirmDelete) => {
  setConfirmDelete({ category, type: "all" });
};

export const confirmDeleteAction = async ({
  confirmDelete,
  setIndicator,
  setLoading,
  setConfirmDelete,
  setRefetch,
  setGetSlider,
  setGetStoredPhotos,
  setGetGalleryPhoto,
  setGetLogos,
}) => {
  if (!confirmDelete) return;
  setIndicator(true);
  const { category, imageUrl, type } = confirmDelete;

  setLoading(true);
  try {
    if (type === "single") {
      await axios.delete("http://localhost:5000/delete-photo", {
        data: { category, url: imageUrl },
      });
      updateUIAfterDelete(category, imageUrl, setGetSlider, setGetStoredPhotos, setGetGalleryPhoto, setGetLogos);
    } else if (type === "all") {
      await axios.delete("http://localhost:5000/delete-category", {
        data: { category },
      });
      updateUIAfterDelete(category, null, setGetSlider, setGetStoredPhotos, setGetGalleryPhoto, setGetLogos);
    }
    setRefetch((prev) => !prev);
  } catch (error) {
    console.error("Delete failed:", error);
  } finally {
    setIndicator(false);
    setLoading(false);
    setConfirmDelete(null);
  }
};
